// docs/geo/building_hist.json is what the page's path produces today: regenerated by
// building_hist.js's own render and compared byte for byte.
"use strict";
const test = require("node:test"), assert = require("node:assert"), fs = require("node:fs");
const { render, OUT, COMMAND } = require("./building_hist.js");

test("building_hist.json is current", () => {
  assert.ok(render(null) === fs.readFileSync(OUT, "utf8"), `docs/geo/building_hist.json is stale: run ${COMMAND}`);
});
